// Weekly digest. The point is not vanity metrics: it is spotting the
// failure mode that hides quietly - a review queue nobody is clearing.
const s = $input.first().json;

const applied  = s.applied ?? 0;
const pending  = s.pending_review ?? 0;
const approved = s.approved ?? 0;
const skipped  = s.skipped ?? 0;
const total    = s.total_applications ?? 0;

const thisWeek = (s.applied_by_day ?? []).reduce((n, d) => n + (d.count ?? 0), 0);

const companies = (s.top_companies ?? [])
  .slice(0, 5)
  .map((c, i) => `  ${i + 1}. ${c.company} (${c.applications})`)
  .join('\n') || '  (none yet)';

const warnings = [];
if (pending > 10) {
  warnings.push(`${pending} jobs have been waiting for review. The agent is doing` +
                ' its half; nothing moves until you look at them.');
}
if (approved > 10) {
  warnings.push(`${approved} jobs are on your shortlist but not applied to yet.`);
}
if (thisWeek === 0 && total > 0) {
  warnings.push('You did not apply to anything this week.');
}

const body = [
  'Job agent - last 7 days',
  '',
  `Applied this week:     ${thisWeek}`,
  `Awaiting your review:  ${pending}`,
  `On your shortlist:     ${approved}`,
  '',
  '--- All time ---',
  `Jobs scored:   ${s.total_jobs_discovered ?? 0}`,
  `Applications:  ${total} (${applied} applied, ${skipped} skipped)`,
  `Average score: ${s.average_score ?? 'n/a'}/100`,
  '',
  '--- Companies you were matched with most ---',
  companies,
  warnings.length ? '\n--- Worth your attention ---\n' + warnings.map(w => `- ${w}`).join('\n') : '',
].join('\n');

return [{
  json: {
    title: warnings.length ? 'Job agent weekly report - action suggested' : 'Job agent weekly report',
    body,
    has_warnings: warnings.length > 0,
    applied_this_week: thisWeek,
    pending_review: pending,
  },
}];

return [{
  json: {
    title: 'Job agent - weekly report unavailable',
    body: [
      'The statistics endpoint could not be reached.',
      '',
      'Check the stack:',
      '  docker compose ps',
      '  curl -fsS http://localhost:8088/health/ready',
    ].join('\n'),
    has_warnings: true,
  },
}];
